package com.coffeeshop.controller;import com.coffeeshop.dto.SettingCommands;import com.coffeeshop.model.SettingModels.Setting;import com.coffeeshop.security.ApplicationSession;import com.coffeeshop.service.SettingService;import javafx.application.Platform;import javafx.beans.property.SimpleStringProperty;import javafx.fxml.FXML;import javafx.geometry.Insets;import javafx.scene.control.*;import javafx.scene.layout.GridPane;import java.util.*;import java.util.concurrent.CompletableFuture;public final class SettingsController{private final SettingService service;private final ApplicationSession session;@FXML private TextField searchField;@FXML private TableView<Setting>settingTable;@FXML private TableColumn<Setting,String>keyColumn,valueColumn,typeColumn,descriptionColumn,updatedColumn;@FXML private Label messageLabel;@FXML private Button editButton;public SettingsController(SettingService s,ApplicationSession a){service=Objects.requireNonNull(s);session=Objects.requireNonNull(a);}@FXML private void initialize(){keyColumn.setCellValueFactory(v->text(v.getValue().key()));valueColumn.setCellValueFactory(v->text(v.getValue().value()));typeColumn.setCellValueFactory(v->text(v.getValue().type()));descriptionColumn.setCellValueFactory(v->text(orDash(v.getValue().description())));updatedColumn.setCellValueFactory(v->text((v.getValue().updatedBy()==null?"System":v.getValue().updatedBy())+" · "+v.getValue().updatedAt().toLocalDate()));searchField.textProperty().addListener((o,a,b)->refresh());settingTable.getSelectionModel().selectedItemProperty().addListener((o,a,b)->editButton.setDisable(b==null));refresh();}@FXML private void refresh(){CompletableFuture.supplyAsync(()->service.settings(searchField.getText())).whenComplete((v,e)->Platform.runLater(()->{if(e!=null){messageLabel.setText("Unable to load settings.");return;}settingTable.getItems().setAll(v);messageLabel.setText(v.isEmpty()?"No settings match the search.":"");}));}@FXML private void add(){editor(null).ifPresent(this::save);}@FXML private void edit(){Setting s=settingTable.getSelectionModel().getSelectedItem();if(s!=null)editor(s).ifPresent(this::save);}private Optional<SettingCommands.Save>editor(Setting s){Dialog<SettingCommands.Save>d=new Dialog<>();d.setTitle(s==null?"Add setting":"Edit setting");ButtonType save=new ButtonType("Save",ButtonBar.ButtonData.OK_DONE);d.getDialogPane().getButtonTypes().addAll(ButtonType.CANCEL,save);TextField key=new TextField(s==null?"":s.key()),value=new TextField(s==null?"":s.value());ComboBox<String>type=new ComboBox<>();type.getItems().setAll("STRING","INTEGER","DECIMAL","BOOLEAN");type.setValue(s==null?"STRING":s.type());TextArea description=new TextArea(s==null||s.description()==null?"":s.description());description.setPrefRowCount(3);GridPane g=new GridPane();g.setHgap(12);g.setVgap(8);g.setPadding(new Insets(8));field(g,0,"Key",key);field(g,1,"Value",value);field(g,2,"Value type",type);field(g,3,"Description",description);d.getDialogPane().setContent(g);d.getDialogPane().setPrefWidth(560);d.setResultConverter(b->b==save?new SettingCommands.Save(s==null?null:s.id(),key.getText(),value.getText(),type.getValue(),description.getText(),s==null?null:s.version()):null);return d.showAndWait();}private void save(SettingCommands.Save q){CompletableFuture.runAsync(()->service.save(q,session.currentUser().orElseThrow().userId())).whenComplete((v,e)->Platform.runLater(()->{if(e==null){refresh();messageLabel.setText("Setting saved.");}else messageLabel.setText(message(e));}));}private static void field(GridPane g,int r,String n,Control c){g.add(new Label(n),0,r);c.setMaxWidth(Double.MAX_VALUE);g.add(c,1,r);}private static SimpleStringProperty text(String s){return new SimpleStringProperty(s);}private static String orDash(String s){return s==null?"-":s;}private static String message(Throwable e){Throwable x=e;while(x.getCause()!=null)x=x.getCause();return x instanceof IllegalArgumentException||x instanceof IllegalStateException?x.getMessage():"Unable to save setting.";}}
